def rotate_left(nums, k):
    if len(nums) == 0:
        return []
    shift = k % len(nums)
    result = []
    for index in range(shift, len(nums)):
        result.append(nums[index])
    for index in range(0, shift):
        result.append(nums[index])
    return result

