def longest_sum_k(nums, k):
    first_seen = {0: -1}
    total = 0
    best = 0
    for index, value in enumerate(nums):
        total += value
        if total - k in first_seen:
            best = max(best, index - first_seen[total - k])
        if total not in first_seen:
            first_seen[total] = index
    return best

