def split_array_largest_sum(nums, k):
    left = max(nums)
    right = sum(nums)
    answer = right

    while left <= right:
        limit = (left + right) // 2
        parts = 1
        current = 0
        for value in nums:
            if current + value > limit:
                parts += 1
                current = value
            else:
                current += value

        if parts <= k:
            answer = limit
            right = limit - 1
        else:
            left = limit + 1

    return answer

